using System;
using System.Collections;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
public class RecoveryFishingVerification:MonoBehaviour {
 string path;void Update(){if(path!=null&&PauseManager.IsPaused)PauseManager.TogglePause(false);}void Record(string s){File.AppendAllText(path,s+"\n");Debug.Log("[RecoveryFishing] "+s);}
 public IEnumerator Run(){path=Path.Combine(RecoveryGiftPanel.EvidencePath,"fishing-verification.txt");File.WriteAllText(path,DateTime.UtcNow.ToString("O")+"\n");var p=Player.LocalPlayer;MainMenuManager.InstantCrash();RecoveryGiftPanel.Instance.SetOpen(false);PauseManager.TogglePause(false);p.Vitals.Heal(100);p.Vitals.RestoreFullness(100);
 var spawn=UnityEngine.Object.FindObjectsByType<SpawnManager>(FindObjectsSortMode.None).First();var boatPrefab=(Boat)typeof(SpawnManager).GetField("_boatPrefab",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(spawn);SaveManager.CurServerSave.UnlockedBoat=true;if(!BoatManager.Boat)BoatManager.Instance.TrySpawnBoat(boatPrefab,SpawnManager.GetBoatSpawnPos(p.Transform.position),SpawnManager.GetBoatSpawnRot(p.Transform.position));yield return new WaitForSecondsRealtime(2);
 Record("boat="+(bool)BoatManager.Boat);var boat=BoatManager.Boat;if(!PlayerManager.InGodMode)PlayerManager.ToggleGodMode();var pos=boat.DriverPos.position+Vector3.up;Record("boat root="+boat.transform.position+" deck="+boat.DriverPos.position);Server.Instance.TeleportPlayer(p,pos,0);yield return new WaitForSecondsRealtime(2);Vector3 away=(pos-Island.IslandPos).normalized;float yaw=Quaternion.LookRotation(new Vector3(away.x,0,away.z)).eulerAngles.y;p.Camera.SetRot(yaw);
 var prefab=Resources.LoadAll<Item>("Items").OfType<FishingRodCast>().First();var rod=(FishingRodCast)ItemManager.Instance.SpawnNewItem(prefab,p.CamObject.position+p.CamObject.forward,Quaternion.identity);rod.PickUp(p,true,true);yield return new WaitForSecondsRealtime(2);Record("held="+(p.Holding.HeldItem==rod)+" bait="+(bool)rod.Bait+" pos="+p.Transform.position);
 InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;GameInfo.Input.ActivateInput();GameInfo.Input.actions.Enable();var kb=InputSystem.AddDevice<Keyboard>("FishingTestKeyboard");var mouse=InputSystem.AddDevice<Mouse>("FishingTestMouse");GameInfo.Input.SwitchCurrentControlScheme("Keyboard",kb,mouse);PlayerCamera.ToggleMouse(false);yield return null;var start=rod.Bait.Rig.position;
 InputSystem.QueueStateEvent(mouse,new MouseState().WithButton(MouseButton.Right));yield return new WaitForSecondsRealtime(1.2f);InputSystem.QueueStateEvent(mouse,new MouseState());yield return new WaitForSecondsRealtime(3);float cast=Vector3.Distance(start,rod.Bait.Rig.position);Record((cast>2?"PASS ":"FAIL ")+"Original right mouse cast: bait distance="+cast+" water="+WaterManager.WaterHeight+" bait="+rod.Bait.Rig.position+" line="+rod.Bait.LineLength);
 yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(RecoveryGiftPanel.EvidencePath,"original-fishing-cast.png"));Record("bait type="+rod.Bait.Info.name+" requiresReeling="+rod.Bait.Info.RequireReelingToCatch);if(rod.Bait.Info.RequireReelingToCatch)InputSystem.QueueStateEvent(mouse,new MouseState().WithButton(MouseButton.Left));float until=Time.realtimeSinceStartup+35;while(!rod.Bait.ItemOnBait&&Time.realtimeSinceStartup<until&&!p.Dying.IsDead){yield return new WaitForSecondsRealtime(1);p.Vitals.Heal(100);p.Vitals.RestoreFullness(100);}Record((rod.Bait.ItemOnBait?"PASS ":"FAIL ")+"Original catch spawn: "+(rod.Bait.ItemOnBait?rod.Bait.ItemOnBait.name:"none")+" underwater="+rod.Bait.TimeUnderWater+" wait="+rod.Bait.RandomizedCatchTime);
 InputSystem.QueueStateEvent(mouse,new MouseState().WithButton(MouseButton.Left));yield return new WaitForSecondsRealtime(8);InputSystem.QueueStateEvent(mouse,new MouseState());Record("Original reel line="+rod.Bait.LineLength+" bait="+rod.Bait.Rig.position);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(RecoveryGiftPanel.EvidencePath,"original-fishing-reel.png"));InputSystem.RemoveDevice(kb);InputSystem.RemoveDevice(mouse);if(Keyboard.current!=null&&Mouse.current!=null)GameInfo.Input.SwitchCurrentControlScheme("Keyboard",Keyboard.current,Mouse.current);if(PlayerManager.InGodMode)PlayerManager.ToggleGodMode();Record("FISHING_VERIFICATION_COMPLETE");}
}
